package model;

/** Represents one row of the 'movies' table. */
public class Movie {

    private int movieId;
    private String title;
    private String genre;
    private String language;
    private int durationMinutes;
    private double rating;
    private String description;

    public Movie() {
    }

    /** Used when adding a new movie (id is generated by the database). */
    public Movie(String title, String genre, String language,
                 int durationMinutes, double rating, String description) {
        this.title = title;
        this.genre = genre;
        this.language = language;
        this.durationMinutes = durationMinutes;
        this.rating = rating;
        this.description = description;
    }

    public Movie(int movieId, String title, String genre, String language,
                 int durationMinutes, double rating, String description) {
        this(title, genre, language, durationMinutes, rating, description);
        this.movieId = movieId;
    }

    /** JComboBox shows this text. */
    @Override
    public String toString() {
        return title;
    }

    public int getMovieId() { return movieId; }
    public void setMovieId(int movieId) { this.movieId = movieId; }
    public String getTitle() { return title; }
    public void setTitle(String title) { this.title = title; }
    public String getGenre() { return genre; }
    public void setGenre(String genre) { this.genre = genre; }
    public String getLanguage() { return language; }
    public void setLanguage(String language) { this.language = language; }
    public int getDurationMinutes() { return durationMinutes; }
    public void setDurationMinutes(int durationMinutes) { this.durationMinutes = durationMinutes; }
    public double getRating() { return rating; }
    public void setRating(double rating) { this.rating = rating; }
    public String getDescription() { return description; }
    public void setDescription(String description) { this.description = description; }
}
